// Paste the endpoint's signing secret from Reach → Webhooks (shown once, rotate if lost).
const SECRET = 'whsec_REPLACE_ME';

const item = $input.first();
const headers = item.json.headers || {};
const sig = headers['reach-signature'] || '';
const parts = Object.fromEntries(sig.split(',').map(p => p.split('=', 2)));
const t = parts.t || '';
const v1 = parts.v1 || '';

// Raw body as Reach signed it (needs the webhook option "Raw Body").
const bin = item.binary && item.binary.data;
const raw = bin ? Buffer.from(bin.data, 'base64').toString('utf8') : JSON.stringify(item.json.body);
const event = JSON.parse(raw);

// Reject replays older than 5 minutes.
const fresh = Math.abs(Date.now() / 1000 - Number(t)) < 300;

return [{ json: { secret: SECRET, signed: `${t}.${raw}`, v1, fresh, event } }];

